"ill/certificate.v": "(* provable (IMALL, intuitionistic, two-sided engine) *)\nLemma certificate : ill (atom := string) intuitionistic [ione; iwith (ivar \"A\") (ivar \"B\"); ilmap (ivar \"B\") (ivar \"C\")] (ivar \"C\").\nProof.\n  apply (soundness_ill String.eqb String.eqb_spec intuitionistic\n    (IOneL (IWithL2 (ivar \"A\") (ivar \"B\") (ILmapL (ivar \"B\") (ivar \"C\") (IAx \"B\") (IAx \"C\"))))).\n  vm_compute. reflexivity.\nQed.\n",
"ill/derivation-ids.svg": "<!-- provable (IMALL, intuitionistic, two‐sided engine) -->\n<svg xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" width=\"181.056\" height=\"110.592\" viewBox=\"0 0 11316 6912\" font-family=\"'Euler Math', 'Neo Euler', serif\" font-size=\"1000\" fill=\"black\">\n<title>1, A &amp; B, B ⊸ C ⊢ C</title>\n<desc>1. B ⊢ B, by ax.\n2. C ⊢ C, by ax.\n3. B, B ⊸ C ⊢ C, by ⊸L from 1 and 2.\n4. A &amp; B, B ⊸ C ⊢ C, by &amp;L₂ from 3.\n5. 1, A &amp; B, B ⊸ C ⊢ C, by 1L from 4.</desc>\n<g fill=\"none\" stroke=\"black\" stroke-width=\"40\">\n<path d=\"M300 5312H9970\"/>\n<path d=\"M855 3812H9416\"/>\n<path d=\"M1098 2312H9172\"/>\n<path d=\"M1098 812H3772\"/>\n<path d=\"M6380 812H9172\"/>\n</g>\n<g id=\"i4\">\n<g id=\"i4-0\">\n<text x=\"300\" y=\"6402\" textLength=\"499\" lengthAdjust=\"spacing\">1</text>\n</g>\n<text x=\"799\" y=\"6402\" textLength=\"277\" lengthAdjust=\"spacing\">,</text>\n<g id=\"i4-1\">\n<text x=\"1409\" y=\"6402\" textLength=\"2828\" lengthAdjust=\"spacing\">𝐴 &amp; 𝐵</text>\n</g>\n<text x=\"4237\" y=\"6402\" textLength=\"277\" lengthAdjust=\"spacing\">,</text>\n<g id=\"i4-2\">\n<text x=\"4847\" y=\"6402\" textLength=\"3045\" lengthAdjust=\"spacing\">𝐵 ⊸ 𝐶</text>\n</g>\n<text x=\"8225\" y=\"6402\" textLength=\"698\" lengthAdjust=\"spacing\">⊢</text>\n<g id=\"i4-3\">\n<text x=\"9256\" y=\"6402\" textLength=\"714\" lengthAdjust=\"spacing\">𝐶</text>\n</g>\n</g>\n<text x=\"10170\" y=\"5512\" textLength=\"846\" lengthAdjust=\"spacing\" font-size=\"800\">1L</text>\n<g id=\"i3\">\n<g id=\"i3-0\">\n<text x=\"855\" y=\"4902\" textLength=\"2828\" lengthAdjust=\"spacing\">𝐴 &amp; 𝐵</text>\n</g>\n<text x=\"3683\" y=\"4902\" textLength=\"277\" lengthAdjust=\"spacing\">,</text>\n<g id=\"i3-1\">\n<text x=\"4293\" y=\"4902\" textLength=\"3045\" lengthAdjust=\"spacing\">𝐵 ⊸ 𝐶</text>\n</g>\n<text x=\"7671\" y=\"4902\" textLength=\"698\" lengthAdjust=\"spacing\">⊢</text>\n<g id=\"i3-2\">\n<text x=\"8702\" y=\"4902\" textLength=\"714\" lengthAdjust=\"spacing\">𝐶</text>\n</g>\n</g>\n<g font-size=\"800\">\n<text x=\"9616\" y=\"4012\" textLength=\"1036\" lengthAdjust=\"spacing\">&amp;L</text>\n<text x=\"10652\" y=\"4132\" textLength=\"280\" lengthAdjust=\"spacing\" font-size=\"560\">2</text>\n</g>\n<g id=\"i2\">\n<g id=\"i2-0\">\n<text x=\"1941\" y=\"3402\" textLength=\"655\" lengthAdjust=\"spacing\">𝐵</text>\n</g>\n<text x=\"2596\" y=\"3402\" textLength=\"277\" lengthAdjust=\"spacing\">,</text>\n<g id=\"i2-1\">\n<text x=\"3206\" y=\"3402\" textLength=\"3045\" lengthAdjust=\"spacing\">𝐵 ⊸ 𝐶</text>\n</g>\n<text x=\"6584\" y=\"3402\" textLength=\"698\" lengthAdjust=\"spacing\">⊢</text>\n<g id=\"i2-2\">\n<text x=\"7615\" y=\"3402\" textLength=\"714\" lengthAdjust=\"spacing\">𝐶</text>\n</g>\n</g>\n<text x=\"9372\" y=\"2512\" textLength=\"1255\" lengthAdjust=\"spacing\" font-size=\"800\">⊸L</text>\n<g id=\"i0\">\n<g id=\"i0-0\">\n<text x=\"1098\" y=\"1902\" textLength=\"655\" lengthAdjust=\"spacing\">𝐵</text>\n</g>\n<text x=\"2086\" y=\"1902\" textLength=\"698\" lengthAdjust=\"spacing\">⊢</text>\n<g id=\"i0-1\">\n<text x=\"3117\" y=\"1902\" textLength=\"655\" lengthAdjust=\"spacing\">𝐵</text>\n</g>\n</g>\n<text x=\"3972\" y=\"1012\" textLength=\"908\" lengthAdjust=\"spacing\" font-size=\"800\">ax</text>\n<g id=\"i1\">\n<g id=\"i1-0\">\n<text x=\"6380\" y=\"1902\" textLength=\"714\" lengthAdjust=\"spacing\">𝐶</text>\n</g>\n<text x=\"7427\" y=\"1902\" textLength=\"698\" lengthAdjust=\"spacing\">⊢</text>\n<g id=\"i1-1\">\n<text x=\"8458\" y=\"1902\" textLength=\"714\" lengthAdjust=\"spacing\">𝐶</text>\n</g>\n</g>\n<text x=\"9372\" y=\"1012\" textLength=\"908\" lengthAdjust=\"spacing\" font-size=\"800\">ax</text>\n</svg>\n",
"ill/derivation.svg": "<!-- provable (IMALL, intuitionistic, two‐sided engine) -->\n<svg xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" width=\"181.056\" height=\"110.592\" viewBox=\"0 0 11316 6912\" font-family=\"'Euler Math', 'Neo Euler', serif\" font-size=\"1000\" fill=\"black\">\n<title>1, A &amp; B, B ⊸ C ⊢ C</title>\n<desc>1. B ⊢ B, by ax.\n2. C ⊢ C, by ax.\n3. B, B ⊸ C ⊢ C, by ⊸L from 1 and 2.\n4. A &amp; B, B ⊸ C ⊢ C, by &amp;L₂ from 3.\n5. 1, A &amp; B, B ⊸ C ⊢ C, by 1L from 4.</desc>\n<g fill=\"none\" stroke=\"black\" stroke-width=\"40\">\n<path d=\"M300 5312H9970\"/>\n<path d=\"M855 3812H9416\"/>\n<path d=\"M1098 2312H9172\"/>\n<path d=\"M1098 812H3772\"/>\n<path d=\"M6380 812H9172\"/>\n</g>\n<text x=\"300\" y=\"6402\" textLength=\"9670\" lengthAdjust=\"spacing\" id=\"i4\">1, 𝐴 &amp; 𝐵, 𝐵 ⊸ 𝐶 ⊢ 𝐶</text>\n<text x=\"10170\" y=\"5512\" textLength=\"846\" lengthAdjust=\"spacing\" font-size=\"800\">1L</text>\n<text x=\"855\" y=\"4902\" textLength=\"8561\" lengthAdjust=\"spacing\" id=\"i3\">𝐴 &amp; 𝐵, 𝐵 ⊸ 𝐶 ⊢ 𝐶</text>\n<g font-size=\"800\">\n<text x=\"9616\" y=\"4012\" textLength=\"1036\" lengthAdjust=\"spacing\">&amp;L</text>\n<text x=\"10652\" y=\"4132\" textLength=\"280\" lengthAdjust=\"spacing\" font-size=\"560\">2</text>\n</g>\n<text x=\"1941\" y=\"3402\" textLength=\"6388\" lengthAdjust=\"spacing\" id=\"i2\">𝐵, 𝐵 ⊸ 𝐶 ⊢ 𝐶</text>\n<text x=\"9372\" y=\"2512\" textLength=\"1255\" lengthAdjust=\"spacing\" font-size=\"800\">⊸L</text>\n<text x=\"1098\" y=\"1902\" textLength=\"2674\" lengthAdjust=\"spacing\" id=\"i0\">𝐵 ⊢ 𝐵</text>\n<text x=\"3972\" y=\"1012\" textLength=\"908\" lengthAdjust=\"spacing\" font-size=\"800\">ax</text>\n<text x=\"6380\" y=\"1902\" textLength=\"2792\" lengthAdjust=\"spacing\" id=\"i1\">𝐶 ⊢ 𝐶</text>\n<text x=\"9372\" y=\"1012\" textLength=\"908\" lengthAdjust=\"spacing\" font-size=\"800\">ax</text>\n</svg>\n",
"ill/derivation.tex": "% provable (IMALL, intuitionistic, two-sided engine)\n\\begin{prooftree}\n\\infer0[$\\mathrm{ax}$]{B &\\vdash B}\n\\infer0[$\\mathrm{ax}$]{C &\\vdash C}\n\\infer2[$\\multimap\\mathrm{L}$]{B, B \\multimap C &\\vdash C}\n\\infer1[$\\with\\mathrm{L}_2$]{A \\with B, B \\multimap C &\\vdash C}\n\\infer1[$\\mathbf{1}\\mathrm{L}$]{\\mathbf{1}, A \\with B, B \\multimap C &\\vdash C}\n\\end{prooftree}\n",
"ill/derivation.typ": "// provable (IMALL, intuitionistic, two-sided engine)\n#prooftree(\n  rule(\n    name: $bold(1) upright(L)$,\n    rule(\n      name: $\\& upright(L)_2$,\n      rule(\n        name: $⊸ upright(L)$,\n        rule(name: $\"ax\"$, $B ⊢ B$),\n        rule(name: $\"ax\"$, $C ⊢ C$),\n        $B, B ⊸ C ⊢ C$,\n      ),\n      $A class(\"binary\", \\&) B, B ⊸ C ⊢ C$,\n    ),\n    $bold(1), A class(\"binary\", \\&) B, B ⊸ C ⊢ C$,\n  ),\n)\n",
"ill/flags.txt": "-i\n",
"ill/fragment.txt": "IMALL\n",
"ill/interact/proof.json": "{\"version\":1,\"sequent\":{\"terms\":[\"⊥\",{\"D\":0},{\"D\":1},{\"⊕\":[1,2]},{\"V\":1},{\"D\":2},{\"⊗\":[4,5]},{\"V\":2}],\"roots\":[0,3,6,7],\"atoms\":[\"A\",\"B\",\"C\"],\"antecedents\":3},\"nodes\":[{\"ax\":[3,5]},{\"ax\":[6,7]},{\"⊗\":[4,0,1]},{\"⊕₂\":[1,2]},{\"⊥\":[0,3]}],\"mode\":\"intuitionistic\"}\n",
