"ill/interact/proof.v": "Lemma certificate : ill (atom := string) intuitionistic [ione; iwith (ivar \"A\") (ivar \"B\"); ilmap (ivar \"B\") (ivar \"C\")] (ivar \"C\").\nProof.\n  apply (soundness_ill String.eqb String.eqb_spec intuitionistic\n    (IOneL (IWithL2 (ivar \"A\") (ivar \"B\") (ILmapL (ivar \"B\") (ivar \"C\") (IAx \"B\") (IAx \"C\"))))).\n  vm_compute. reflexivity.\nQed.\n",
"ill/interact/script.txt": "goals\nshow\nshow --svg ill/interact/state-0.svg\nsave ill/interact/state-0.json\napply 0 0 1L\ngoals\nshow\nshow --svg ill/interact/state-1.svg\nsave ill/interact/state-1.json\napply 1 0 &L2\ngoals\nshow\nshow --svg ill/interact/state-2.svg\nsave ill/interact/state-2.json\napply 2 1 -oL 0\ngoals\nshow\nshow --svg ill/interact/state-3.svg\nsave ill/interact/state-3.json\napply 3 0 ax\ngoals\nshow\nshow --svg ill/interact/state-4.svg\nsave ill/interact/state-4.json\napply 4 0 ax\ngoals\nshow\nshow --svg ill/interact/state-5.svg\nsave ill/interact/state-5.json\nproof\nproof --svg ill/interact/proof.svg\nproof ill/interact/proof.json\nproof --rocq ill/interact/proof.v\nquit\n",
