"mll/interact/proof.v": "Lemma certificate (A B : formula) : ll [parr (dual A) (dual B); tens B A].\nProof.\napply (parr_r_ext []); cbn_sequent.\napply (ex_perm_r [2; 0; 1] [dual B; tens B A; dual A]).\napply (tens_r_ext [dual B]); cbn_sequent.\n{\n  ax_expansion.\n}\n{\n  ax_expansion.\n}\nQed.\n",
"mll/interact/script.txt": "goals\nshow\nshow --svg mll/interact/state-0.svg\nsave mll/interact/state-0.json\napply 0 0 par\ngoals\nshow\nshow --svg mll/interact/state-1.svg\nsave mll/interact/state-1.json\napply 1 2 * 1\ngoals\nshow\nshow --svg mll/interact/state-2.svg\nsave mll/interact/state-2.json\napply 2 0 ax\ngoals\nshow\nshow --svg mll/interact/state-3.svg\nsave mll/interact/state-3.json\napply 3 0 ax\ngoals\nshow\nshow --svg mll/interact/state-4.svg\nsave mll/interact/state-4.json\nproof\nproof --svg mll/interact/proof.svg\nproof mll/interact/proof.json\nproof --rocq mll/interact/proof.v\nquit\n",
